	static fromPlain({
		character,
		name,
		mnemonic,
		audioUrl,
		priority,
		lesson,
		sceneMnemonic,
	}: {
		character: string;
		name: string;
		mnemonic?: string;
		audioUrl?: string;
		priority?: number;
