		// reads as a phrase. Field names like "sourceFlags" and tags like
		// "lesson-notes" carry no space and survive this.
		expect(raw.match(/[A-Za-z]{3,}\s+[A-Za-z]{3,}/)?.[0]).toBeUndefined();
